import{_ as e,o as a,c as i,am as t}from"./chunks/framework.yj4qiWdr.js";const k=JSON.parse('{"title":"Cartographie et scan réseau","description":"","frontmatter":{"title":"Cartographie et scan réseau","aside":true,"prev":false,"next":false},"headers":[],"relativePath":"bug-bounty/scan-reseau.md","filePath":"bug-bounty/scan-reseau.md"}'),n={name:"bug-bounty/scan-reseau.md"};function l(r,s,p,h,o,d){return a(),i("div",null,s[0]||(s[0]=[t('<h1 id="cartographie-et-scan-reseau" tabindex="-1">Cartographie et scan réseau <a class="header-anchor" href="#cartographie-et-scan-reseau" aria-label="Permalink to &quot;Cartographie et scan réseau&quot;">​</a></h1><p><a href="./">Retour au parcours</a></p><p>Objectif : identifier les services réellement présents, les ports autorisés et les technologies, sans confondre un CDN ou un hébergement partagé avec le périmètre.</p><h2 id="validation-dns-et-http" tabindex="-1">Validation DNS et HTTP <a class="header-anchor" href="#validation-dns-et-http" aria-label="Permalink to &quot;Validation DNS et HTTP&quot;">​</a></h2><p>Vérifier l&#39;appartenance des noms collectés au scope avant les requêtes actives. Les exemples de fichiers historiques utilisent plusieurs noms ; sélectionner explicitement les fichiers de la méthode choisie.</p><h3 id="dnsx-validation-dns" tabindex="-1">DNSX - validation DNS <a class="header-anchor" href="#dnsx-validation-dns" aria-label="Permalink to &quot;DNSX - validation DNS&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">dnsx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> all_subs.txt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -silent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> resolved_subs.txt</span></span></code></pre></div><p>Identifie les noms qui répondent aux requêtes DNS.</p><h3 id="dnsx-resolution-inverse" tabindex="-1">DNSX - résolution inverse <a class="header-anchor" href="#dnsx-resolution-inverse" aria-label="Permalink to &quot;DNSX - résolution inverse&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">dnsx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -ptr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> resolved_subs.txt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -resp-only</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> reverse_dns.txt</span></span></code></pre></div><p>Interroge les enregistrements PTR ; utiliser une liste d&#39;adresses IP pour une résolution inverse pertinente, plutôt qu&#39;une liste de noms.</p><h3 id="httpx-metadonnees-des-services" tabindex="-1">HTTPX - métadonnées des services <a class="header-anchor" href="#httpx-metadonnees-des-services" aria-label="Permalink to &quot;HTTPX - métadonnées des services&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">httpx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> resolved_subs.txt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> 80,443,8080,8443</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -silent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -title</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -sc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -ip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> live_websites.txt</span></span></code></pre></div><p>Identifie les services HTTP répondants et collecte titres, codes et adresses IP. Utiliser HTTPX de ProjectDiscovery.</p><h3 id="filtrage-des-sous-domaines-actifs" tabindex="-1">Filtrage des sous-domaines actifs <a class="header-anchor" href="#filtrage-des-sous-domaines-actifs" aria-label="Permalink to &quot;Filtrage des sous-domaines actifs&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> subexample.com.txt</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;"> httpx-toolkit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -ports</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> 80,443,8080,8000,8888</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -threads</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> 200</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> subexample.coms_alive.txt</span></span></code></pre></div><p>Vérifie les réponses HTTP sur plusieurs ports et enregistre les hôtes répondants.</p><blockquote><p>La commande emploie une concurrence élevée. Respecter les limites du programme.</p></blockquote><h3 id="httprobe-services-web" tabindex="-1">Httprobe - services Web <a class="header-anchor" href="#httprobe-services-web" aria-label="Permalink to &quot;Httprobe - services Web&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> resolved_subs.txt</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;"> httprobe</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> live_websites.txt</span></span></code></pre></div><p>Alternative de détection des services HTTP et HTTPS. Le fichier de sortie est écrasé.</p><h2 id="scan-reseau" tabindex="-1">Scan réseau <a class="header-anchor" href="#scan-reseau" aria-label="Permalink to &quot;Scan réseau&quot;">​</a></h2><h3 id="inventaire-des-ports-avec-naabu" tabindex="-1">Inventaire des ports avec Naabu <a class="header-anchor" href="#inventaire-des-ports-avec-naabu" aria-label="Permalink to &quot;Inventaire des ports avec Naabu&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">naabu</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -list</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> ip.txt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> 50</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -nmap-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> &#39;nmap -sV -SC&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> naabu-full.txt</span></span></code></pre></div><p>Associe Naabu et Nmap pour identifier des ports et services.</p><h3 id="scan-complet-avec-nmap" tabindex="-1">Scan complet avec Nmap <a class="header-anchor" href="#scan-complet-avec-nmap" aria-label="Permalink to &quot;Scan complet avec Nmap&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">nmap</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -p-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> --min-rate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> 1000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -T4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -A</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -oA</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> fullscan</span></span></code></pre></div><p>Analyse l&#39;ensemble des ports TCP et collecte des informations sur les services.</p><blockquote><p>Débit et options intrusives à vérifier selon les règles du programme.</p></blockquote><h3 id="scan-avec-masscan" tabindex="-1">Scan avec Masscan <a class="header-anchor" href="#scan-avec-masscan" aria-label="Permalink to &quot;Scan avec Masscan&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">masscan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -p0-65535</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> --rate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> 100000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -oG</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> masscan-results.txt</span></span></code></pre></div><p>Exemple historique de scan de ports à débit très élevé.</p><blockquote><p>Débit extrêmement élevé dans l&#39;original ; ne pas exécuter sur des systèmes tiers.</p></blockquote><h2 id="reconnaissance-visuelle" tabindex="-1">Reconnaissance visuelle <a class="header-anchor" href="#reconnaissance-visuelle" aria-label="Permalink to &quot;Reconnaissance visuelle&quot;">​</a></h2><h3 id="aquatone-captures-des-services-web" tabindex="-1">Aquatone - captures des services Web <a class="header-anchor" href="#aquatone-captures-des-services-web" aria-label="Permalink to &quot;Aquatone - captures des services Web&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> hosts.txt</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;"> aquatone</span></span></code></pre></div><p>Génère des captures et un rapport visuel à partir d&#39;une liste de services Web autorisés. Préparer <code>hosts.txt</code> avec les hôtes validés et vérifier les dépendances du logiciel. Aquatone est un outil historique ; sa compatibilité actuelle n&#39;a pas été testée.</p><h3 id="cartographie-asn-et-ip" tabindex="-1">Cartographie ASN et IP <a class="header-anchor" href="#cartographie-asn-et-ip" aria-label="Permalink to &quot;Cartographie ASN et IP&quot;">​</a></h3><p>Identifier les réseaux et les systèmes autonomes associés à une organisation, puis comparer les résultats avec le périmètre explicitement autorisé. Une association ASN, DNS ou IP ne suffit pas à établir qu&#39;un actif peut être testé. Cette étape complète l&#39;énumération des sous-domaines sans répéter les commandes existantes.</p><h3 id="checklist-de-reconnaissance" tabindex="-1">Checklist de reconnaissance <a class="header-anchor" href="#checklist-de-reconnaissance" aria-label="Permalink to &quot;Checklist de reconnaissance&quot;">​</a></h3><ul><li>[ ] Collecte passive et déduplication des sous-domaines.</li><li>[ ] Validation DNS et contrôle du scope.</li><li>[ ] Inventaire HTTP et identification des technologies.</li><li>[ ] Cartographie ASN/IP et reconnaissance visuelle.</li><li>[ ] Collecte des URL, paramètres et références JavaScript.</li><li>[ ] Inventaire des interfaces API et des fonctionnalités.</li><li>[ ] Vérification manuelle des observations et préparation du rapport.</li></ul><h2 id="nmap-rapport-xml-local" tabindex="-1">Nmap - rapport XML local <a class="header-anchor" href="#nmap-rapport-xml-local" aria-label="Permalink to &quot;Nmap - rapport XML local&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">nmap</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -sV</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> 8000,8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -oX</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> nmap_out.xml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> 127.0.0.1</span></span></code></pre></div><p>Produit un inventaire XML des deux ports du laboratoire local. Adaptation pour alimenter le parseur Nmap présenté dans le workflow de scanning.</p><h2 id="workflow-de-scanning-et-fuzzing" tabindex="-1">Workflow de scanning et fuzzing <a class="header-anchor" href="#workflow-de-scanning-et-fuzzing" aria-label="Permalink to &quot;Workflow de scanning et fuzzing&quot;">​</a></h2><p>L&#39;article organise le travail en six étapes. Les commandes déjà documentées dans la cheatsheet ne sont pas répétées.</p><ol><li><strong>Chaos</strong> : collecte des sous-domaines.</li><li><strong>HTTPX</strong> : validation HTTP et inventaire, déduplication des résultats.</li><li><strong>Naabu</strong> : inventaire des ports expressément autorisés.</li><li><strong>Nmap</strong> : identification des services et production de résultats XML.</li><li><strong>Nuclei</strong> : contrôle des configurations et vulnérabilités connues dans le périmètre de test.</li><li><strong>FFUF</strong> : découverte de contenu dans un laboratoire autorisé.</li></ol><p>Ne pas assimiler une adresse IP partagée, un CDN ou un service tiers à un actif autorisé. Vérifier le scope avant tout scan. Comparer les codes HTTP, la taille des réponses et le nombre de mots pour distinguer les réponses génériques des résultats pertinents ; un 403 doit être respecté.</p><h3 id="nmap-conversion-xml-en-html" tabindex="-1">Nmap - conversion XML en HTML <a class="header-anchor" href="#nmap-conversion-xml-en-html" aria-label="Permalink to &quot;Nmap - conversion XML en HTML&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">./nmap-parse-output</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> nmap_out.xml</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> html</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> scan.html</span></span></code></pre></div><p>Convertit un rapport Nmap XML déjà produit en document HTML, sans effectuer de nouvelle requête. Adapter le chemin au fichier local. La syntaxe est reprise de l&#39;article avec un chemin générique.</p><p><a href="https://github.com/ernw/nmap-parse-output" target="_blank" rel="noreferrer">Script nmap-parse-output</a></p><hr><p><a href="./reconnaissance">Précédent : Reconnaissance passive</a> · <a href="./">Parcours</a> · <a href="./cartographie-web">Suivant : Cartographie Web et API</a></p>',54)]))}const u=e(n,[["render",l]]);export{k as __pageData,u as default};
